export type AttachmentKind = "text" | "table" | "blob" | "sealed" | "opaque";

export interface Attachment {
  readonly kind: AttachmentKind;
  readonly name: string;
  readonly bytes: readonly number[];
}

export interface PackingRequest {
  readonly command: "pack" | "pk";
  readonly attachment?: Attachment;
}

export interface PackingRecord {
  readonly name: string;
  readonly kind: "text" | "table" | "blob";
  readonly sourceBytes: number;
}

export type PackingOutcome =
  | { readonly status: "limited" }
  | { readonly status: "missing" }
  | { readonly status: "ignored" }
  | { readonly status: "packed"; readonly data: readonly number[]; readonly record: PackingRecord };

export function executePacking(request: PackingRequest, limited: boolean): PackingOutcome {
  if (limited) return { status: "limited" };
  if (request.command !== "pack" && request.command !== "pk") throw new RangeError("unknown command");
  const attachment = request.attachment;
  if (!attachment) return { status: "missing" };
  if (attachment.name.trim().length === 0) throw new RangeError("blank name");
  if (attachment.bytes.some((value) => !Number.isInteger(value) || value < 0 || value > 255)) {
    throw new RangeError("invalid byte");
  }
  if (attachment.kind === "sealed" || attachment.kind === "opaque") return { status: "ignored" };
  const data = (attachment.bytes as number[]).reverse();
  return {
    status: "packed",
    data,
    record: { name: attachment.name, kind: attachment.kind, sourceBytes: attachment.bytes.length },
  };
}

