import * as S from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}
function findArray(value: Record<string, unknown>): unknown[] | undefined {
  return Object.keys(value).map((key) => value[key]).find((item): item is unknown[] => Array.isArray(item));
}
function findRecord(value: Record<string, unknown>): Record<string, unknown> | undefined {
  return Object.keys(value).map((key) => value[key]).find((item): item is Record<string, unknown> => item !== null && typeof item === 'object' && !Array.isArray(item));
}

const bypass = S.executePacking({ command: 'bad', attachment: { kind: 'text', name: '', bytes: [999] } } as unknown as S.PackingRequest, true) as any;
deepEqual(bypass, { status: 'limited' }, 'limited bypasses all request validation');
throwsRange(() => S.executePacking({ command: 'zip' } as unknown as S.PackingRequest, false), 'unsupported runtime command');

deepEqual(S.executePacking({ command: 'pack' } as S.PackingRequest, false), { status: 'missing' }, 'pack without attachment');
deepEqual(S.executePacking({ command: 'pk' } as S.PackingRequest, false), { status: 'missing' }, 'pk alias without attachment');

const bytes = [0, 1, 127, 255];
const request = { command: 'pack', attachment: { kind: 'text', name: ' data ', bytes } } as S.PackingRequest;
const before = JSON.stringify(request);
const packed = S.executePacking(request, false) as any;
equal(packed.status, 'packed', 'supported attachment is packed');
const packedBytes = findArray(packed as Record<string, unknown>);
assert(packedBytes !== undefined, 'packed result contains a byte array');
deepEqual(packedBytes, [255, 127, 1, 0], 'bytes are reversed');
assert(packedBytes !== bytes, 'output bytes do not alias input');
const record = findRecord(packed as Record<string, unknown>);
assert(record !== undefined, 'packed result contains a record');
assert(Object.values(record).some((value) => value === ' data '), 'record preserves name');
assert(Object.values(record).some((value) => value === 'text'), 'record preserves kind');
assert(Object.values(record).some((value) => value === 4), 'record contains byte count');
equal(JSON.stringify(request), before, 'request is not mutated');

const again = S.executePacking(request, false) as any;
const againBytes = findArray(again as Record<string, unknown>);
const againRecord = findRecord(again as Record<string, unknown>);
assert(again !== packed, 'successful result object is newly allocated');
assert(againBytes !== packedBytes, 'successful byte arrays are independent');
assert(againRecord !== record, 'successful records are independent');
packedBytes[0] = 42;
deepEqual(againBytes, [255, 127, 1, 0], 'one output cannot mutate another');

for (const kind of ['table', 'blob']) {
  const result = S.executePacking({ command: 'pk', attachment: { kind, name: 'x', bytes: [] } } as S.PackingRequest, false) as any;
  equal(result.status, 'packed', `${kind} is supported`);
  deepEqual(findArray(result), [], `${kind} accepts empty bytes`);
}
for (const kind of ['sealed', 'opaque']) {
  const result = S.executePacking({ command: 'pack', attachment: { kind, name: 'x', bytes: [1] } } as S.PackingRequest, false) as any;
  deepEqual(result, { status: 'ignored' }, `${kind} is ignored`);
}

throwsRange(() => S.executePacking({ command: 'pack', attachment: { kind: 'text', name: ' \t ', bytes: [] } } as S.PackingRequest, false), 'blank name');
for (const invalid of [-1, 256, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsRange(() => S.executePacking({ command: 'pack', attachment: { kind: 'text', name: 'x', bytes: [invalid] } } as S.PackingRequest, false), `invalid byte ${String(invalid)}`);
}
throwsRange(() => S.executePacking({ command: 'pack', attachment: { kind: 'sealed', name: 'x', bytes: [256] } } as S.PackingRequest, false), 'ignored data is validated before ignoring');

